    uri_to_ts[r['point_uri']]= (r['timeseries_id'], r['point_class'])

# Find zones with both temperature sensor and cooling setpoint
byzone=defaultdict(dict)
for uri,(ts,cls) in uri_to_ts.items():
    # extract zone: pattern #Zone_FX_ZYY.<Class>
    if '#Zone_' in uri and '.' in uri:
        base, cls2 = uri.split('#',1)[1].rsplit('.',1)
        byzone[base][cls2]= (ts)

candidates={}
for z,d in byzone.items():
    if 'Zone_Air_Temperature_Sensor' in d and 'Zone_Air_Cooling_Temperature_Setpoint' in d:
        candidates[z]=(d['Zone_Air_Temperature_Sensor'], d['Zone_Air_Cooling_Temperature_Setpoint'])

print(len(candidates))
