input.sparql:
SELECT ?label WHERE {
  ?z a brick:HVAC_Zone .
  FILTER (contains(str(?z), "Zone_F2_Z07") || contains(str(?z), "Zone_F2_Z08") || contains(str(?z), "Zone_F4_Z01"))
  OPTIONAL { ?z rdfs:label ?label }
  FILTER (bound(?label))
}

SELECT ?zone ?label WHERE {
  ?sp a brick:Zone_Air_Cooling_Temperature_Setpoint .
  FILTER (contains(str(?sp), "Zone_F2_Z07"))
  ?sp brick:isPointOf ?zone .
  FILTER (a(?zone))
}

SELECT ?suffix ?label WHERE {
  ?sp a brick:Zone_Air_Cooling_Temperature_Setpoint .
  ?sp brick:isPointOf ?zone .
  FILTER (regex(str(?sp), "(Zone_F2_Z07|Zone_F2_Z01)$"))
  OPTIONAL {?zone rdfs:label ?label}
  BIND(replace(str(?sp),"^.*/","") AS ?suffix)
}

SELECT ?point ?zone ?label WHERE {
  ?sp ref:hasExternalReference ?e .
  ?sp a brick:Zone_Air_Cooling_Temperature_Setpoint .
  FILTER (contains(str(?sp), "Zone_F2_Z07"))
  ?sp brick:isPointOf ?zone .
  OPTIONAL {?zone rdfs:label ?label}
}
